    (1315772, 'Minions & Monsters', 'This is the rambunctious, ridiculous and totally true story of how the Minions conquered Hollywood, became movie stars, lost everything, unleashed monsters onto the world and then banded together to try and save the planet from the mayhem they had just created.', 90, 'Pierre Coffin', 'Pierre Coffin, Trey Parker, Christoph Waltz, Allison Janney, Jesse Eisenberg', 'English, Finnish, Swedish', '7', ARRAY['Adventure','Animation','Comedy','Family','Fantasy'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/4LwvU9SZc8QQzW1X1FAPhNbXnEU.jpg', 'https://www.youtube.com/watch?v=V-O-uBaHk3c', '2026-06-24', 'now_showing'),
    (1465063, 'Forgotten Island', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', 109, 'Januel Mercado', 'H.E.R., Liza Soberano, Dave Franco, Jenny Slate, Manny Jacinto', 'English, Finnish, Swedish', 'S', ARRAY['Animation','Adventure','Fantasy','Comedy','Family'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', 'https://www.youtube.com/watch?v=PhgY8cOJiQA', '2026-09-10', 'now_showing'),
    (1400837, 'Other Mommy', 'Young Bela forms a relationship with a sinister entity in her home that looks uncannily like her own mother, drawing her into a terrifying and increasingly dark world.', 93, 'Rob Savage', 'Jessica Chastain, Jay Duplass, Arabella Olivia Clark, Karen Allen, Arian Moayed', 'English, Finnish, Swedish', '16', ARRAY['Horror'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/fGRNCssTRrhYZxNzykGGCoMsAVq.jpg', 'https://www.youtube.com/watch?v=-mnTITqqiT0', '2026-10-07', 'now_showing'),
    (1263337, 'Heart of the Beast', 'After a harrowing plane crash, Special Forces officer James Belmont and his combat dog, Odin, find themselves stranded deep in the Alaskan wilderness. Together, they are forced into a brutal fight for survival against the elements.', 101, 'David Ayer', 'Brad Pitt, J.K. Simmons, Anna Lambe, Justin Melnick, Shaun DeZern', 'English, Finnish, Swedish', '12', ARRAY['Adventure','Thriller'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/6sYemVUn79UPKz1ZsSG6kPU4RVy.jpg', 'https://www.youtube.com/watch?v=UkMuGKqAux4', '2026-09-19', 'now_showing'),
    (1503762, 'Sense and Sensibility', 'A charming, witty, and deeply relatable story of love and sisterhood.', 132, 'Georgia Oakley', 'Daisy Edgar-Jones, Esmé Creed-Miles, Caitríona Balfe, Frank Dillane, Herbert Nordrum', 'English, Finnish, Swedish', '7', ARRAY['Romance','Drama','History'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/czsyPHosFNbh4PPqXfqWu1aBXnA.jpg', 'https://www.youtube.com/watch?v=OFLyW0lxFU0', '2026-09-23', 'now_showing'),
    (1423191, 'Resident Evil', 'Medical courier Bryan unwittingly finds himself fighting for survival as one fateful, horrifying night collapses around him in chaos.', 94, 'Zach Cregger', 'Austin Abrams, Paul Walter Hauser, Kali Reis, Zach Cherry, Johnno Wilson', 'English, Finnish, Swedish', '16', ARRAY['Horror','Science Fiction','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/gAgWJhUSQWCgtKR8170nMkYlBda.jpg', 'https://www.youtube.com/watch?v=mNd1gb19A-c', '2026-09-16', 'now_showing'),
    (1400940, 'Clayface', 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', 109, 'James Watkins', 'Tom Rhys Harries, Naomi Ackie, Eddie Marsan, Max Minghella, David Dencik', 'English, Finnish, Swedish', '16', ARRAY['Horror','Thriller','Science Fiction'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/9l1NuFjel2j89hiuiJbsxfblqjy.jpg', 'https://www.youtube.com/watch?v=f7jlCqdtwdM', '2026-10-19', 'now_showing'),
    (940721, 'Godzilla Minus One', 'In postwar Japan, Godzilla brings new devastation to an already scorched landscape. With no military intervention or government help in sight, the survivors must join together in the face of despair and fight back against an unrelenting horror.', 125, 'Takashi Yamazaki', 'Ryunosuke Kamiki, Minami Hamabe, Yuki Yamada, Munetaka Aoki, Hidetaka Yoshioka', 'English, Finnish, Swedish', '12', ARRAY['Science Fiction','Horror','Action'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/2E2WTX0TJEflAged6kzErwqX1kt.jpg', 'https://www.youtube.com/watch?v=MSp68m8OJus', '2023-11-03', 'now_showing'),
    (1477104, 'Shaun the Sheep: The Beast of Mossy Bottom', 'On Halloween Eve at Mossy Bottom Farm, excitement turns to dismay when the clumsy Farmer ruins the pumpkin patch. Shaun tries fixing it with science experiments, but things go awry when a wild beast appears in the woods.', 81, 'Steve Cox', 'Justin Fletcher, John Sparkes, Nina Sosanya, Kate Harbour, Rich Webber', 'English, Finnish, Swedish', '7', ARRAY['Animation','Science Fiction','Comedy','Family'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/gayX49siwXf8eNs16rtk1fI91Ey.jpg', 'https://www.youtube.com/watch?v=daZMq0AyOMc', '2026-09-17', 'now_showing'),
    (1291595, 'Insidious: Out of the Further', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', 106, 'Jacob Chase', 'Amelia Eve, Island Austin, Brandon Perea, Lin Shaye, Maisie Richardson-Sellers', 'English, Finnish, Swedish', '16', ARRAY['Horror','Thriller'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 'https://www.youtube.com/watch?v=gXjurDkYnEM', '2026-08-19', 'now_showing'),
    (1283515, 'Verity', 'Lowen Ashleigh, hired to ghostwrite for best-selling author Verity Crawford, uncovers Verity''s autobiographical notes, and becomes involved in what may prove to be a lethal conspiracy.', 117, 'Michael Showalter', 'Dakota Johnson, Anne Hathaway, Josh Hartnett, Brady Wagner, Ismael Cruz Cordova', 'English, Finnish, Swedish', '12', ARRAY['Mystery','Thriller'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/rmaNMA1seHqpjtnYKzyynFAr1g8.jpg', 'https://www.youtube.com/watch?v=xdPMKhjMSFs', '2026-09-30', 'now_showing'),
    (1314481, 'The Devil Wears Prada 2', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', 119, 'David Frankel', 'Meryl Streep, Anne Hathaway, Emily Blunt, Stanley Tucci, Kenneth Branagh', 'English, Finnish, Swedish', '7', ARRAY['Comedy','Drama'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/fCAURTUx3YfsJ8k9I0UamjSILiR.jpg', 'https://www.youtube.com/watch?v=PMd1at7OwiE', '2026-04-29', 'now_showing'),
    (969681, 'Spider-Man: Brand New Day', 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', 145, 'Destin Daniel Cretton', 'Tom Holland, Sadie Sink, Tramell Tillman, Zendaya, Jacob Batalon', 'English, Finnish, Swedish', '12', ARRAY['Science Fiction','Action','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://www.youtube.com/watch?v=P3uI5sLosKU', '2026-07-29', 'now_showing'),
    (1003596, 'Avengers: Doomsday', 'Beloved heroes from three distinct universes are set on a deadly collision course and face an existential threat unlike anything they''ve ever encountered.', 165, 'Joe Russo', 'Robert Downey Jr., Chris Evans, Chris Hemsworth, Pedro Pascal, Paul Rudd', 'English, Finnish, Swedish', '12', ARRAY['Science Fiction','Action','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/9jlZ59UALLLOE279HMT19rP9XQs.jpg', 'https://www.youtube.com/watch?v=X1aFkAkFASk', '2026-12-16', 'coming_soon'),
    (1170608, 'Dune: Part Three', 'Nearly two decades after he seized control of the Imperium, Paul Atreides is now a ruthless Emperor, and must face the consequences of his reign as old allies return, terrifying new threats emerge, and betrayal lurks in every shadow. Haunted by visions of Imperial collapse and the reappearance of his long-lost love, Paul is drawn into a sweeping conspiracy, with Chani at the heart of its unfolding mystery. As enemies close in, Paul must confront the true cost of power and the fate of those he loves the most.', 150, 'Denis Villeneuve', 'Timothée Chalamet, Zendaya, Jason Momoa, Florence Pugh, Rebecca Ferguson', 'English, Finnish, Swedish', '12', ARRAY['Science Fiction','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/glt0v4I89rMWstDNCaFXc5SNyO1.jpg', 'https://www.youtube.com/watch?v=uJqaGLmZpGo', '2026-12-15', 'coming_soon'),
    (1300968, 'The Hunger Games: Sunrise on the Reaping', 'Return to the world of Panem 24 years before the events of The Hunger Games, starting on the morning of the reaping of the 50th Hunger Games, also known as the Second Quarter Quell.', 159, 'Francis Lawrence', 'Joseph Zada, Mckenna Grace, Maya Hawke, Ralph Fiennes, Jesse Plemons', 'English, Finnish, Swedish', '16', ARRAY['Science Fiction','Action','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/jNcZH8yplxttRlf0wwqfGGMKHxX.jpg', 'https://www.youtube.com/watch?v=Dr060OLTodE', '2026-11-18', 'coming_soon'),
    (1260649, 'Jumanji: Open World', 'Our heroes have escaped the ever-changing jungles of Jumanji before, but this time the game comes to us—as Jumanji breaks free of its console, unleashing its chaos into our world.', 120, 'Jake Kasdan', 'Dwayne Johnson, Kevin Hart, Jack Black, Karen Gillan, Awkwafina', 'English, Finnish, Swedish', '12', ARRAY['Adventure','Comedy','Fantasy'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/ntjF2gemedf3ZcWzARGt6cuZlnJ.jpg', 'https://www.youtube.com/watch?v=nIw1O3zvOfE', '2026-12-23', 'coming_soon'),
    (1440769, 'The Beekeeper 2', 'Pulled back into the fight when the Beekeeper organization goes rogue and sets its sights on controlling the government, Clay must take on the very group that made him.', 105, 'Timo Tjahjanto', 'Jason Statham, Jeremy Irons, Yara Shahidi, Emmy Raver-Lampman, Bobby Naderi', 'English, Finnish, Swedish', '16', ARRAY['Action','Crime','Thriller'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/xlutnD8qZkrZmaDVyzIRCJlrUPp.jpg', 'https://www.youtube.com/watch?v=5HK3wimDxBI', '2027-01-13', 'coming_soon'),
    (1288438, 'Godzilla x Kong: Supernova', 'Godzilla and Kong return in an all-new adventure as Earth''s greatest titans face an unthinkable threat from beyond the stars. When a cosmic predator, Apex, sets its sights on Earth, only the combined might of monsters and humanity can avert total extinction.', 115, 'Grant Sputore', 'Kaitlyn Dever, Dan Stevens, Jack O''Connell, Delroy Lindo, Matthew Modine', 'English, Finnish, Swedish', '12', ARRAY['Science Fiction','Action','Adventure'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/gEGDDG6QMDFZ1sV32CGxvzaVPnv.jpg', NULL, '2027-03-25', 'coming_soon'),
    (1384758, 'Ice Age: Boiling Point', 'A dinosaur-and-lava-filled madcap adventure takes Manny, Sid, Diego, Ellie, Buck, acorn-obsessed Scrat – this time joined by Baby Scrat and the enormous Jurassic Scrat – and the rest of the herd to visit never before-seen corners of the treacherous Lost World.', 103, 'John Donkin', 'Ray Romano, John Leguizamo, Denis Leary, Simon Pegg, Queen Latifah', 'English, Finnish, Swedish', 'S', ARRAY['Adventure','Animation','Family','Comedy'], ARRAY['Finnish','Swedish'], 'https://image.tmdb.org/t/p/w500/mPhAreyZLLcZ9pl4KRyEaqSu1Zv.jpg', NULL, '2027-01-28', 'coming_soon');
